from typing import Dict

# Define local request, response, and normalization helpers for Federated Login Flow

class OAuthRequest:
    def __init__(self, client_id: str, client_secret: str, scopes: Dict[str, str]):
        self.client_id = client_id
        self.client_secret = client_secret
        self.scopes = scopes

class OAuthResponse:
    def __init__(self, access_token: str, refresh_token: str, id_token: str, expires_in: int):
        self.access_token = access_token
        self.refresh_token = refresh_token
        self.id_token = id_token
        self.expires_in = expires_in

def normalize_claims(claims: Dict[str, str]) -> Dict[str, str]:
    normalized_claims = {
        'sub': claims['sub'],
        'name': claims.get('name', ''),
        'email': claims.get('email', ''),
        'picture': claims.get('picture', '')
    }
    return normalized_claims

# This module should be used to define request, response, and normalization helpers for the Federated Login Flow.

import json

# Summarize federated-login audit events
def summarize_audit_events(audit_events):
    summarized_events = []
    for event in audit_events:
        summarized_event = {
            'event_id': event['event_id'],
            'user_id': event['user_id'],
            'timestamp': event['timestamp'],
            'action': event['action'],
            'details': event['details']
        }
        summarized_events.append(summarized_event)
    return json.dumps(summarized_events, indent=2)

# This function should be called with a list of audit events to summarize.

import re

# Moderate free-text claims or notes
def moderate_claims(claims):
    moderated_claims = {}
    for key, value in claims.items():
        if isinstance(value, str):
            moderated_value = re.sub(r'[^a-zA-Z0-9\s]', '', value)
            moderated_claims[key] = moderated_value
        else:
            moderated_claims[key] = value
    return moderated_claims

